def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # remove if present (expired or not) to reinsert
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                else:
                    del cache[key]
            # clean expired entries lazily is optional, but need to check capacity
            # count only non-expired entries as occupying capacity
            # First, if key not present now, check capacity
            if key not in cache:
                # evict if needed, but only count valid (non-expired) entries
                while len(cache) >= capacity:
                    # find least recently used
                    oldest_key = next(iter(cache))
                    if is_expired(oldest_key, t):
                        del cache[oldest_key]
                    else:
                        if len(cache) >= capacity:
                            del cache[oldest_key]
                        else:
                            break
            cache[key] = (value, t)
            cache.move_to_end(key)
        else:
            _, t, key = op
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

